local _, WFJ = ...
WFJ.Data.add("spell", {
  [440014] = { nil, "Infligge $N1 danni da fuoco ogni $D1.", nil, 0xe0649799, "mu" },
  [440054] = { "Crea uno spirito d'ombra che attacca il bersaglio. L'incantatore riceve il $N1% di mana quando lo Spirito d'Ombra attacca. Dura $D1.", nil, 0x609469be, nil, "um" },
  [440483] = { nil, "Danni fisici inflitti aumentati del $N1%.", nil, 0x07715b9c, "mu" },
  [440488] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [440492] = { "Incidi sul tuo mantello la runa Carne Fresca:\n\n$I1\nDanneggiare un bersaglio con Sete di Sangue, Assalto Mortale o Colpo di Scudo ha una probabilità del $N1% la prima volta e del $N2% ogni volta successiva di farti infuriare (attivando le abilità che richiedono di essere infuriati) e di farti infliggere il $N3% di danni fisici in più per $D1.", nil, 0x5a6bf051, nil, "um" },
  [440494] = { "Incidi sul tuo mantello la runa Morte Improvvisa:\n\n$I1\nI tuoi colpi in mischia hanno una probabilità del $N1% di conferire Morte Improvvisa. Morte Improvvisa consente un uso di Esecuzione indipendentemente dalla salute del bersaglio. Quando Esecuzione è resa possibile da Morte Improvvisa, conservi $N2 rabbia dopo averla usata.", nil, 0x6d800699, nil, "um" },
  [440496] = { "Incidi sul tuo mantello la runa Onda d'Urto:\n\n$I1\nScatena un'onda di forza davanti al Guerriero, che infligge $N1 danni e stordisce tutti i nemici entro $N2 m in un cono frontale per $D1.", nil, 0x56e19117, nil, "um" },
  [440505] = { "Conferisce a chi lo beve l'invisibilità per $D1.", "Invisibilità", 0x3fdd20e3, 0x757e6c9b, "uu" },
  [440557] = { "Incidi sul tuo mantello la runa Parsimonia:\n\n$I1\nRiduce del $N1% il costo in mana delle tue trappole e delle tue abilità in mischia, e conferisce ai colpi critici delle tue abilità in mischia e a distanza una probabilità del $N2% di far proseguire il $N3% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0x5c9e589a, nil, "um" },
  [440560] = { "Incidi sul tuo mantello la runa Improved Volley:\n\n$I1\nRiduce il costo in mana di Raffica del $N1%, ne riduce il tempo di recupero del $N2%, ne aumenta i danni del $N3% e Raffica non subisce più ritardi di lancio dagli attacchi che infliggono danni. Inoltre, Raffica infligge come danni aggiuntivi il $N4% della tua potenza d'attacco a distanza ogni volta che infligge danni.", nil, 0x20ba9081, nil, "um" },
  [440563] = { "Incidi sul tuo mantello la runa Incidente con Fuga:\n\n$I1\nOttieni il $N1% di velocità di movimento per $D1 dopo aver usato Assalto del Raptor.\n\nLe abilità offensive del tuo famiglio fanno cadere il bersaglio in una Frenesia Idrofoba, che ne aumenta la potenza d'attacco in mischia di $N3 ma ne riduce l'Armatura di $N4 per $D2. I nemici idrofobi non fuggono e ignorano gli effetti di paura e di orrore.", nil, 0x15040a9f, nil, "um" },
  [440574] = { nil, "Immobilizzato.", nil, 0x9bb1efcf, "mu" },
  [440586] = { "Stordisce il bersaglio per $D1.", "Stordito.", 0xb330d181, 0x27f95286, "uu" },
  [440630] = { "Incidi sul tuo mantello la runa Spirito Ferino:\n\n$I1\nEvoca due Spirit Wolves al comando dello Sciamano per $D1.", nil, 0x3a18cf25, nil, "um" },
  [440632] = { "+$N1 potenza d'attacco solo in Forma Felina, Forma d'Orso e Dire Bear Form.", nil, 0xa798bce2, nil, "um" },
  [440634] = { "Incidi sul tuo mantello la runa Tempesta, Terra e Fuoco:\n\n$I1\nRiduce il tempo di recupero di Catena di Fulmini del $N1%, fa sì che il tuo Totem del Vincolo Terrestre immobilizzi i bersagli per $D1 quando viene posato e aumenta del $N3% i danni periodici inflitti da Folgore del Fuoco.", nil, 0xb99a4382, nil, "um" },
  [440788] = { "Incidi sul tuo mantello la runa Shield of Righteousness:\n\n$I1\nColpisce il bersaglio con lo scudo, infliggendo danni da sacro basati sul tuo indice di blocco più altri $N1 danni.", nil, 0xb62d614f, nil, "um" },
  [440790] = { "Incidi sul tuo mantello la runa Dominio Rapido:\n\n$I1\nQuando Giusta Furia non è attiva, infliggere danni con Folgore Sacra ti conferisce il $N1% del tuo Intelletto come danni magici e riduce la minaccia che generi del $N2% per $D1.\n\nSe è incisa Infusione di Luce, ottieni Luce Solare per $D2.\n\n$I2\nLuce Solare fa sì che Tempesta Divina, Assalto del Crociato e gli attacchi in mischia contro bersagli non controllati da giocatori infliggano danni da sacro aggiuntivi pari al $N5% della tua potenza magica sacra.", nil, 0x21f37d6a, nil, "um" },
  [440792] = { "Incidi sul tuo mantello la runa Righteous Vengeance:\n\n$I1\nQuando Giudizio o Assalto del Crociato infliggono un colpo critico, il bersaglio subisce il $N1% di danni aggiuntivi in $D1.", nil, 0xdd37e14e, nil, "um" },
  [440809] = { nil, "Velocità di movimento ridotta del $N1%.", nil, 0x09876d53, "mu" },
  [440858] = { "Incidi sul tuo mantello la runa Globo Congelato:\n\n$I1\nLancia un globo di ghiaccio vorticante che avanza rapidamente per $D1. Mentre si muove, ogni $D2 il globo infligge $N3 danni da gelo e applica un Gelo che riduce del $N4% la velocità di movimento di tutti i nemici che attraversa. La prima volta che danneggia un nemico, il suo movimento rallenta e ha una probabilità del $N5% di attivare la runa Dita di Gelo.", nil, 0xf8b56c74, nil, "um" },
  [440892] = { nil, "Resistenze magiche ridotte di $N1. Danni magici subiti aumentati del $N2%.", nil, 0x96faf3fe, "mu" },
  [440922] = { "Incidi sui tuoi stivali la runa Decimazione:\n\n$I1\nRiduce del $N1% il tempo di recupero di Fuoco dell'Anima. Quando lanci Dardo d'Ombra o Dolore Ustionante su un nemico sotto il $N2% della salute, questi infliggono il $N3% di danni in più e per i successivi $D1 il tuo Fuoco dell'Anima ha il tempo di lancio ridotto del $N5% e non costa Soul Shard.", nil, 0x19ab4ac7, nil, "um" },
  [440924] = { "Incidi sul tuo mantello la runa Marchio del Caos:\n\n$I1\nMaledice il bersaglio per $D1, riducendone le resistenze magiche di $N2 e aumentando i danni magici che subisce del $N3%. Su un bersaglio può essere attiva una sola maledizione per Stregone.", nil, 0x050e05a1, nil, "um" },
  [440926] = { "Incidi sul tuo mantello la runa Armatura Infernale:\n\n$I1\nIl tuo spirito si infonde di energia demoniaca, riducendo tutti i danni magici che subisci di una percentuale pari al $N1% della tua riduzione dei danni fisici dovuta all'Armatura. Dura $D1.", nil, 0x32bd63f1, nil, "um" },
})
